export const FASTING = {
  title: "Optional: a day of prayer and fasting",
  body: "Many Christians set aside a day to fast and give focused time to prayer. Choose what is wise for you: skip one meal and pray in that time, keep to simple meals, or step away from social media for the day. Fasting is a way of giving God your attention. It is not a way to earn anything.",
  care: "Fasting from food is not right for everyone. If you are pregnant, under 18, take medication, have a medical condition, or have struggled with eating, choose a media fast or skip this. Break any food fast gently.",
};

export const dayNumber = (d: Date) => Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000);

export function adviceFor(cat: CatKey, ageDays: number | null, connected: boolean): string | null {
  if (ageDays !== null && ageDays >= 30)
    return "You have carried this one for a while. An unanswered prayer is not a sign of too little faith. Keep bringing it, and consider talking it over with a pastor or a mature friend.";
  if (cat === "relationship" && connected) return "Consider praying this one together tonight, even for two minutes.";
  if (cat === "health") return "Pray alongside seeing a doctor, not instead of it.";
  if (cat === "work") return "Pair your prayer with one practical step today, like asking for advice or sending that application.";
  return null;
}
